import ephemeris from '../data/horizons-2026-01-01.json';
import type { Vec3 } from '../types';

/**
 * Initial state vectors from JPL Horizons (DE441-based), generated by scripts/fetch-horizons.mjs.
 * Epoch 2026-01-01 00:00 TDB, ecliptic J2000 frame, Solar System Barycentre origin, au and au/day.
 */
export interface InitialState {
  position: Vec3;
  velocity: Vec3;
  horizonsName: string;
}

export const EPOCH_JD_TDB: number = ephemeris.epoch.jdTDB;
export const EPOCH_LABEL = `${ephemeris.epoch.calendarTDB} TDB`;
export const EPHEMERIS_META = { frame: ephemeris.frame, origin: ephemeris.origin, source: ephemeris.source };

const states = ephemeris.states as Record<string, { r: number[]; v: number[]; horizonsName: string }>;

export function initialStateFor(id: string): InitialState {
  const s = states[id];
  if (!s) throw new Error(`No Horizons initial state for body "${id}"`);
  return { position: s.r as Vec3, velocity: s.v as Vec3, horizonsName: s.horizonsName };
}
